#include <stdlib.h>
#include <string.h>
#include <float.h>
typedef double cost;
/* Dense LAPJV. c: n*n row-major. x[i]=col of row i. */
int lapjv(int n, const cost *c, int *x, cost *u, cost *v){
  int *y=malloc(n*sizeof(int)), *freer=malloc(n*sizeof(int)), *collist=malloc(n*sizeof(int)),
      *matches=calloc(n,sizeof(int)), *pred=malloc(n*sizeof(int));
  cost *d=malloc(n*sizeof(cost));
  int i,j,k,numfree=0;
  for(j=n-1;j>=0;j--){ cost m=c[j]; int im=0; for(i=1;i<n;i++) if(c[i*n+j]<m){m=c[i*n+j];im=i;}
    v[j]=m; if(++matches[im]==1){x[im]=j;y[j]=im;} else y[j]=-1; }
  for(i=0;i<n;i++){ if(matches[i]==0) freer[numfree++]=i;
    else if(matches[i]==1){ int j1=x[i]; cost m=DBL_MAX; const cost*ci=c+(size_t)i*n;
      for(j=0;j<n;j++) if(j!=j1 && ci[j]-v[j]<m) m=ci[j]-v[j]; v[j1]-=m; } }
  for(int loop=0;loop<2;loop++){
    int kk=0, prv=numfree; numfree=0;
    while(kk<prv){
      i=freer[kk++]; const cost*ci=c+(size_t)i*n;
      cost u1=ci[0]-v[0], u2=DBL_MAX; int j1=0,j2=-1;
      for(j=1;j<n;j++){ cost h=ci[j]-v[j]; if(h<u2){ if(h>=u1){u2=h;j2=j;} else {u2=u1;u1=h;j2=j1;j1=j;} } }
      int i0=y[j1];
      if(u1<u2) v[j1]-=u2-u1;
      else if(i0>=0){ j1=j2; i0=y[j1]; }
      if(i0>=0){ if(u1<u2) freer[--kk]=i0; else freer[numfree++]=i0; }
      x[i]=j1; y[j1]=i;
    }
  }
  for(int f=0;f<numfree;f++){
    int fr=freer[f], low, up, last, endofpath=-1;
    const cost*cf=c+(size_t)fr*n;
    for(j=0;j<n;j++){ d[j]=cf[j]-v[j]; pred[j]=fr; collist[j]=j; }
    low=0; up=0; cost mn=0;
    int unassigned=0;
    while(1){
      if(up==low){
        last=low-1; mn=d[collist[up++]];
        for(k=up;k<n;k++){ j=collist[k]; cost h=d[j];
          if(h<=mn){ if(h<mn){ up=low; mn=h; } collist[k]=collist[up]; collist[up++]=j; } }
        for(k=low;k<up;k++) if(y[collist[k]]<0){ endofpath=collist[k]; unassigned=1; break; }
        if(unassigned) break;
      }
      int j1=collist[low++]; i=y[j1]; const cost*ci=c+(size_t)i*n;
      cost u1=ci[j1]-v[j1]-mn;
      for(k=up;k<n;k++){ j=collist[k]; cost h=ci[j]-v[j]-u1;
        if(h<d[j]){ pred[j]=i; if(h==mn){ if(y[j]<0){endofpath=j;unassigned=1;break;} collist[k]=collist[up]; collist[up++]=j; } d[j]=h; } }
      if(unassigned) break;
    }
    for(k=0;k<=last;k++){ int j1=collist[k]; v[j1]+=d[j1]-mn; }
    do{ i=pred[endofpath]; y[endofpath]=i; int j1=endofpath; endofpath=x[i]; x[i]=j1; }while(i!=fr);
  }
  for(i=0;i<n;i++){ u[i]=c[(size_t)i*n+x[i]]-v[x[i]]; }
  free(y);free(freer);free(collist);free(matches);free(pred);free(d);
  return 0;
}
