{"command": "export TMPDIR=$PWD/tmp; cat > slap.c <<'EOF'
#include <stdlib.h>
#include <string.h>
#include <float.h>
#include <math.h>
typedef struct { double d; int j; } HE;
static void hpush(HE*h,int*hs,double d,int j){int k=(*hs)++;while(k>0){int p=(k-1)>>1;if(h[p].d<=d)break;h[k]=h[p];k=p;}h[k].d=d;h[k].j=j;}
static HE hpop(HE*h,int*hs){HE top=h[0];HE last=h[--(*hs)];int k=0,n=*hs;while(1){int c=2*k+1;if(c>=n)break;if(c+1<n&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[k]=h[c];k=c;}if(n>0)h[k]=last;return top;}
static double qsel(double*a,int n,int k){int l=0,r=n-1;while(l<r){double p=a[(l+r)>>1];int i=l,j=r;while(i<=j){while(a[i]<p)i++;while(a[j]>p)j--;if(i<=j){double t=a[i];a[i]=a[j];a[j]=t;i++;j--;}}if(k<=j)r=j;else if(k>=i)l=i;else return a[k];}return a[k];}

/* returns number of verification rounds, or -1 on failure */
int slap(int n, const double*c, int K, int*x){
  int *adj=malloc((size_t)n*n*sizeof(int)), *deg=calloc(n,sizeof(int));
  unsigned char *in=calloc((size_t)n*n,1);
  int *y=malloc(n*sizeof(int)), *pred=malloc(n*sizeof(int)), *touched=malloc(n*sizeof(int)), *done=calloc(n,sizeof(int));
  int *freer=malloc(n*sizeof(int));
  double *v=calloc(n,sizeof(double)), *d=malloc(n*sizeof(double)), *tmp=malloc(n*sizeof(double));
  HE *heap=malloc(((size_t)n*n+n)*sizeof(HE));
  int i,j;
  if(K>n)K=n;
  for(i=0;i<n;i++){ const double*ci=c+(size_t)i*n; memcpy(tmp,ci,n*sizeof(double)); double th=qsel(tmp,n,K-1);
    for(j=0;j<n;j++) if(ci[j]<=th && !in[(size_t)i*n+j]){in[(size_t)i*n+j]=1;adj[(size_t)i*n+deg[i]++]=j;} }
  for(j=0;j<n;j++){ for(i=0;i<n;i++) tmp[i]=c[(size_t)i*n+j]; double th=qsel(tmp,n,K-1);
    for(i=0;i<n;i++) if(c[(size_t)i*n+j]<=th && !in[(size_t)i*n+j]){in[(size_t)i*n+j]=1;adj[(size_t)i*n+deg[i]++]=j;} }
  for(i=0;i<n;i++){x[i]=-1;} for(j=0;j<n;j++){y[j]=-1;d[j]=INFINITY;}
  int nf=0; for(i=0;i<n;i++) freer[nf++]=i;
  int rounds=0;
  while(1){
    for(int f=0;f<nf;f++){
      int fr=freer[f];
      int hs=0,nt=0,end=-1; double mn=0;
      const double*cf=c+(size_t)fr*n; int*af=adj+(size_t)fr*n;
      for(int t=0;t<deg[fr];t++){ j=af[t]; double h=cf[j]-v[j]; if(h<d[j]){ if(d[j]==INFINITY) touched[nt++]=j; d[j]=h; pred[j]=fr; hpush(heap,&hs,h,j);} }
      int nscan=0;
      while(hs>0){
        HE e=hpop(heap,&hs); j=e.j; if(done[j]||e.d>d[j]) continue;
        done[j]=1; touched[nt]=touched[nt]; 
        if(y[j]<0){end=j;mn=e.d;break;}
        nscan++;
        i=y[j]; const double*ci=c+(size_t)i*n; int*ai=adj+(size_t)i*n;
        double u1=ci[j]-v[j]-e.d;
        for(int t=0;t<deg[i];t++){ int k=ai[t]; if(done[k]) continue; double h=ci[k]-v[k]-u1;
          if(h<d[k]){ if(d[k]==INFINITY) touched[nt++]=k; d[k]=h; pred[k]=i; hpush(heap,&hs,h,k);} }
      }
      if(end<0){ /* make row dense and retry */
        for(int t=0;t<nt;t++){int k=touched[t];d[k]=INFINITY;done[k]=0;}
        for(j=0;j<n;j++) if(!in[(size_t)fr*n+j]){in[(size_t)fr*n+j]=1;adj[(size_t)fr*n+deg[fr]++]=j;}
        /* could also need other rows dense; mark all rows dense worst case */
        int alld=1; for(i=0;i<n;i++) if(deg[i]<n){alld=0;break;}
        if(alld && deg[fr]==n){ /* should not happen */ }
        /* to guarantee progress, densify all rows if this row was already dense */
        f--; 
        static int guard=0; if(++guard>4*n){ for(i=0;i<n;i++) for(j=0;j<n;j++) if(!in[(size_t)i*n+j]){in[(size_t)i*n+j]=1;adj[(size_t)i*n+deg[i]++]=j;} }
        continue;
      }
      for(int t=0;t<nt;t++){ int k=touched[t]; if(done[k] && d[k]<mn) v[k]+=d[k]-mn; d[k]=INFINITY; done[k]=0; }
      do{ i=pred[end]; y[end]=i; int j1=end; end=x[i]; x[i]=j1; }while(i!=fr);
    }
    /* verify on full matrix */
    rounds++; nf=0;
    for(i=0;i<n;i++){ const double*ci=c+(size_t)i*n; double ui=ci[x[i]]-v[x[i]]; int bad=0;
      for(j=0;j<n;j++){ if(ci[j]-v[j] < ui-1e-13){ if(!in[(size_t)i*n+j]){in[(size_t)i*n+j]=1;adj[(size_t)i*n+deg[i]++]=j;} bad=1; } }
      if(bad) freer[nf++]=i; }
    if(nf==0) break;
    for(int f=0;f<nf;f++){ i=freer[f]; y[x[i]]=-1; x[i]=-1; }
    if(rounds>50){rounds=-1;break;}
  }
  free(adj);free(deg);free(in);free(y);free(pred);free(touched);free(done);free(freer);free(v);free(d);free(tmp);free(heap);
  return rounds;
}
