{"command": "export TMPDIR=$PWD/tmp; cat > slap2.c <<'EOF'
#include <stdlib.h>
#include <string.h>
#include <math.h>
typedef struct { double d; int j; } HE;
static inline void hpush(HE*h,int*hs,double d,int j){int k=(*hs)++;while(k>0){int p=(k-1)>>1;if(h[p].d<=d)break;h[k]=h[p];k=p;}h[k].d=d;h[k].j=j;}
static inline HE hpop(HE*h,int*hs){HE top=h[0];HE last=h[--(*hs)];int k=0,n=*hs;while(1){int c=2*k+1;if(c>=n)break;if(c+1<n&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[k]=h[c];k=c;}if(n>0)h[k]=last;return top;}

typedef struct { int *j; int deg, cap; } Row;
static void addedge(Row*r,int j){ if(r->deg==r->cap){ r->cap=r->cap*2+8; r->j=realloc(r->j,r->cap*sizeof(int)); } r->j[r->deg++]=j; }

/* Exact LAP (min sum c[i][x[i]]). Sparse candidate graph, full dual verification.
   returns rounds>0 on success, -1 on failure. */
int slap(int n, const double*c, double t, int*x){
  Row *R=calloc(n,sizeof(Row));
  unsigned char *in=calloc((size_t)n*n,1);
  int *y=malloc(n*sizeof(int)), *pred=malloc(n*sizeof(int)), *touched=malloc(n*sizeof(int));
  char *done=calloc(n,1);
  int *freer=malloc(n*sizeof(int)), *cargmin=malloc(n*sizeof(int));
  double *v=malloc(n*sizeof(double)), *d=malloc(n*sizeof(double));
  int heapcap=1024; HE *heap=malloc(heapcap*sizeof(HE));
  int i,j,rounds=0,ok=1;
  for(j=0;j<n;j++){v[j]=INFINITY;cargmin[j]=0;}
  for(i=0;i<n;i++){
    const double*ci=c+(size_t)i*n; unsigned char*ini=in+(size_t)i*n;
    int cnt=0; double rm=INFINITY; int ra=0;
    for(j=0;j<n;j++){ double h=ci[j]; if(!(h<INFINITY) ){ ok=0; } if(h<t) cnt++; if(h<rm){rm=h;ra=j;} if(h<v[j]){v[j]=h;cargmin[j]=i;} }
    R[i].cap=cnt+4; R[i].j=malloc(R[i].cap*sizeof(int));
    for(j=0;j<n;j++) if(ci[j]<t){ R[i].j[R[i].deg++]=j; ini[j]=1; }
    if(!ini[ra]){ini[ra]=1;addedge(&R[i],ra);}
  }
  if(!ok){ rounds=-1; goto out; }
  for(j=0;j<n;j++){ i=cargmin[j]; if(!in[(size_t)i*n+j]){in[(size_t)i*n+j]=1;addedge(&R[i],j);} }
  /* column reduction + greedy */
  for(i=0;i<n;i++) x[i]=-1;
  for(j=0;j<n;j++){ y[j]=-1; d[j]=INFINITY; }
  for(j=n-1;j>=0;j--){ i=cargmin[j]; if(x[i]<0){ x[i]=j; y[j]=i; } }
  int nf=0; for(i=0;i<n;i++) if(x[i]<0) freer[nf++]=i;
  int densified=0;
  while(1){
    for(int f=0;f<nf;f++){
      int fr=freer[f];
      int hs=0,nt=0,end=-1; double mn=0;
      const double*cf=c+(size_t)fr*n; Row*rf=&R[fr];
      for(int q=0;q<rf->deg;q++){ j=rf->j[q]; double h=cf[j]-v[j]; if(h<d[j]){ if(d[j]==INFINITY) touched[nt++]=j; d[j]=h; pred[j]=fr; if(hs==heapcap){heapcap*=2;heap=realloc(heap,heapcap*sizeof(HE));} hpush(heap,&hs,h,j);} }
      while(hs>0){
        HE e=hpop(heap,&hs); j=e.j; if(done[j]||e.d>d[j]) continue;
        done[j]=1;
        if(y[j]<0){end=j;mn=e.d;break;}
        i=y[j]; const double*ci=c+(size_t)i*n; Row*ri=&R[i];
        double u1=ci[j]-v[j]-e.d;
        for(int q=0;q<ri->deg;q++){ int k=ri->j[q]; if(done[k]) continue; double h=ci[k]-v[k]-u1;
          if(h<d[k]){ if(d[k]==INFINITY) touched[nt++]=k; d[k]=h; pred[k]=i; if(hs==heapcap){heapcap*=2;heap=realloc(heap,heapcap*sizeof(HE));} hpush(heap,&hs,h,k);} }
      }
      if(end<0){
        for(int q=0;q<nt;q++){int k=touched[q];d[k]=INFINITY;done[k]=0;}
        if(densified){ rounds=-1; goto out; }
        for(i=0;i<n;i++) for(j=0;j<n;j++) if(!in[(size_t)i*n+j]){in[(size_t)i*n+j]=1;addedge(&R[i],j);}
        densified=1; f--; continue;
      }
      for(int q=0;q<nt;q++){ int k=touched[q]; if(done[k] && d[k]<mn) v[k]+=d[k]-mn; d[k]=INFINITY; done[k]=0; }
      do{ i=pred[end]; y[end]=i; int j1=end; end=x[i]; x[i]=j1; }while(i!=fr);
    }
    rounds++; nf=0;
    for(i=0;i<n;i++){ const double*ci=c+(size_t)i*n; double ui=ci[x[i]]-v[x[i]]-1e-12; int bad=0;
      for(j=0;j<n;j++){ if(ci[j]-v[j] < ui){ if(!in[(size_t)i*n+j]){in[(size_t)i*n+j]=1;addedge(&R[i],j);} bad=1; } }
      if(bad) freer[nf++]=i; }
    if(nf==0) break;
    for(int f=0;f<nf;f++){ i=freer[f]; y[x[i]]=-1; x[i]=-1; }
    if(rounds>100){rounds=-1;break;}
  }
out:
  for(i=0;i<n;i++) free(R[i].j);
  free(R);free(in);free(y);free(pred);free(touched);free(done);free(freer);free(cargmin);free(v);free(d);free(heap);
  return rounds;
}
