cat > solver.py <<'EOF'
import os, ctypes
import numpy as np
import ot

_lib = ctypes.CDLL(os.path.join(os.path.dirname(os.path.abspath(__file__)), "libslap.so"))
_lib.slap.argtypes = [ctypes.c_int, ctypes.c_void_p, ctypes.c_double, ctypes.c_void_p]
_lib.slap.restype = ctypes.c_int
DEG = float(os.environ.get("SLAP_DEG", "12"))
_rng = np.random.default_rng(0)


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = a.shape[0]
        if n > 1 and b.shape[0] == n and M.shape == (n, n) and np.all(a == a[0]) and np.all(b == a[0]):
            # Uniform equal marginals: an optimal vertex of the transportation polytope
            # is a scaled permutation matrix (Birkhoff), so solve the assignment problem
            # exactly (sparse candidate edges + full-matrix dual optimality verification).
            flat = M.ravel()
            s = flat[_rng.integers(0, flat.size, 4096)]
            t = float(np.quantile(s, min(1.0, DEG / n)))
            x = np.empty(n, dtype=np.int32)
            r = _lib.slap(n, M.ctypes.data, t, x.ctypes.data)
            if r > 0:
                G = np.zeros((n, n))
                G[np.arange(n), x] = a[0]
                return {"transport_plan": G}
        G = ot.lp.emd(a, b, M, check_marginals=False)
        return {"transport_plan": G}
