/* Row adjacency: SoA arrays with capacity */
typedef struct { int *j; double *c; int deg, cap; } Row;
static inline void addedge(Row*r,int j,double c){ if(r->deg==r->cap){ r->cap=r->cap*2+16; r->j=realloc(r->j,r->cap*sizeof(int)); r->c=realloc(r->c,r->cap*sizeof(double)); } r->j[r->deg]=j; r->c[r->deg]=c; r->deg++; }
static inline double redmin(const double*a,const double*v,int n){ double m0=INFINITY,m1=INFINITY,m2=INFINITY,m3=INFINITY; int j=0;
  for(;j+4<=n;j+=4){ double h0=a[j]-v[j],h1=a[j+1]-v[j+1],h2=a[j+2]-v[j+2],h3=a[j+3]-v[j+3]; m0=h0<m0?h0:m0; m1=h1<m1?h1:m1; m2=h2<m2?h2:m2; m3=h3<m3?h3:m3; }
