/* indexed 4-ary heap */
typedef struct { int *h; int *pos; double *key; int size; } IH;
static inline void ih_up(IH*H,int k){ int*h=H->h; int*pos=H->pos; double*key=H->key; int j=h[k]; double kj=key[j];
  while(k>0){ int p=(k-1)>>2; if(key[h[p]]<=kj) break; h[k]=h[p]; pos[h[k]]=k; k=p; } h[k]=j; pos[j]=k; }
static inline void ih_down(IH*H,int k){ int*h=H->h; int*pos=H->pos; double*key=H->key; int n=H->size; int j=h[k]; double kj=key[j];
  while(1){ int c=4*k+1; if(c>=n) break; int best=c; double bk=key[h[c]]; int e=c+4<n?c+4:n;
    for(int q=c+1;q<e;q++){ double kq=key[h[q]]; if(kq<bk){bk=kq;best=q;} }
    if(bk>=kj) break; h[k]=h[best]; pos[h[k]]=k; k=best; } h[k]=j; pos[j]=k; }
