    for(int f=0;f<nf;f++){ i=freer[f]; y[x[i]]=-1; x[i]=-1; }
    if(rounds>500){ rounds=-1; break; }
  }
out:
  if(NTH>1) pool_park();
  for(i=0;i<n;i++) if(R[i].own){ free(R[i].j); free(R[i].c); R[i].own=0; }
  return rounds;
}
